window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c5d8de8aa2c6efaf"]={"versions": [{"id": "FIG-c5d8de8aa2c6efaf", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (AUTOSAR M2-Metamodell-Ausschnitt, Release R2.1.20).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Definition der Metaklassen für anwendungsspezifische Annotationen (<code>ApplicationAttributes</code>) im Rahmen der Sender-Receiver-Kommunikation. Dient der formalen semantischen Spezifikation von Daten- und Dienstgüteeigenschaften (Quality of Service / Signal-Eigenschaften) an Software-Component-Ports (VFB-Ebene), bevor diese auf konkrete RTE- und Com-Mechanismen abgebildet werden.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen und Attribute</p>\n<ul class=\"fig-list\">\n<li><strong><code>ApplicationAttributes::PortAnnotation</code>:</strong></li>\n<li>Abstrakte Basisklasse für alle portbezogenen Metadaten-Annotationen.</li>\n<li><strong><code>ApplicationAttributes::SenderReceiverAnnotation</code>:</strong></li>\n<li>Spezialisierung von <code>PortAnnotation</code>.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>computed: Boolean</code> – Flag, ob der Datenwert zur Laufzeit berechnet oder direkt übernommen wird.</li>\n<li><code>limitType: Enumeration{ none, min, max }</code> – Spezifikation von Wertebereichsgrenzen (Grenzprüfung).</li>\n<li><code>processingType: Enumeration{ none, raw, filtered }</code> – Art der Signalverarbeitung vor Weitergabe (Rohwert vs. Vorverarbeitung).</li>\n<li><strong><code>ApplicationAttributes::SenderAnnotation</code>:</strong></li>\n<li>Spezialisierung von <code>SenderReceiverAnnotation</code> zur Spezifikation von Eigenschaften auf Senderseite (P-Port-Kontext).</li>\n<li><strong><code>ApplicationAttributes::ReceiverAnnotation</code>:</strong></li>\n<li>Spezialisierung von <code>SenderReceiverAnnotation</code> für die Empfängerseite (R-Port-Kontext).</li>\n<li><strong>Attribut:</strong></li>\n<li><code>signalAge: Float</code> – Maximal zulässiges Signalalter bzw. Latenz-/Timeout-Toleranz des Signals.</li>\n<li><strong><code>PortInterface::DataElementPrototype</code> (Kategorie <code>DataPrototype</code>):</strong></li>\n<li>Schnittstellenelement eines Sender-Receiver-PortInterface.</li>\n<li><strong>Attribut:</strong></li>\n<li><code>infoType: Enumeration{ data, event }</code> – Semantische Unterscheidung zwischen periodischem/unqued Werttransport (<code>data</code>) und queued/ereignisgetriebenem Nachrichtentransport (<code>event</code>).</li>\n<li><strong><code>ApplicationAttributes::ExtAnnotation</code>:</strong></li>\n<li>Generische Erweiterungsstruktur für proprietäre oder werkzeugspezifische Metadaten.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>name: String</code></li>\n<li><code>value: String</code></li>\n<li><strong>Paket <code>BM Software-Component</code> (Behavior Modeling):</strong></li>\n<li>Übergeordnetes Paket, das die Modellelemente importiert.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong>Vererbung:</strong></li>\n<li><code>SenderReceiverAnnotation</code> erbt von <code>PortAnnotation</code>.</li>\n<li><code>SenderAnnotation</code> und <code>ReceiverAnnotation</code> erben von <code>SenderReceiverAnnotation</code>.</li>\n<li><strong>Assoziation <code>+dataElement</code>:</strong></li>\n<li>Stereotyp: <code>«instanceRef»</code></li>\n<li>Kardinalität: <code>0..1</code> (<code>SenderReceiverAnnotation</code>) zu <code>1</code> (<code>DataElementPrototype</code>).</li>\n<li>Kontextbezogene Referenzierung des konkreten Datenelements innerhalb des Schnittstellenkontexts.</li>\n<li><strong>Komposition <code>+extAnnotations</code>:</strong></li>\n<li><code>SenderReceiverAnnotation</code> aggregiert via Komposition <code>0..*</code> Instanzen von <code>ExtAnnotation</code>.</li>\n<li><strong>Paket-Abhängigkeiten:</strong></li>\n<li><code>BM Software-Component</code> besitzt <code>«import»</code>-Abhängigkeiten zu <code>PortInterface::DataElementPrototype</code>, <code>ApplicationAttributes::PortAnnotation</code>, <code>ApplicationAttributes::SenderReceiverAnnotation</code> und <code>ApplicationAttributes::ReceiverAnnotation</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Charakter:</strong> Rein statisches M2-Strukturdiagramm; kein direktes Laufzeit-Sequenzdiagramm.</li>\n<li><strong>Statisch determinierte Laufzeitsemantik:</strong></li>\n<li>Die Instanziierung dieser Metaklassen in M1-Beschreibungen (ARXML) steuert die Codegenerierung des RTE-Laufzeitverhaltens:</li>\n<li><code>infoType == event</code> erzwingt Queueing-Mechanismen im RTE-Puffer (<code>Rte_Send</code> / <code>Rte_Receive</code>) mit FIFO-Ablauf.</li>\n<li><code>infoType == data</code> führt zu Last-Is-Best-Semantik (<code>Rte_Write</code> / <code>Rte_Read</code>) ohne Pufferung.</li>\n<li><code>signalAge</code> parametriert Empfangs-Überwachungslogiken (Alive Supervision / Timeout-Monitor im RTE-Task-Kontext). Bei Überschreitung erfolgt die Rückgabe von Fehlercodes (z. B. <code>RTE_E_TIMEOUT</code> / <code>RTE_E_NEVER_RECEIVED</code>) oder Aktivierung von Invalidierungs-/Default-Werten.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE-API-Vertrag:</strong></li>\n<li>Die Modellierung von <code>infoType</code> entscheidet direkt über die generierten C-Funktionssignaturen und Pufferallokationen:</li>\n<li><code>data</code>: Nicht-blockierende Lese-/Schreibzugriffe (implicit/explicit Data Access).</li>\n<li><code>event</code>: Queue-basierte Schnittstellen mit Fehlerstatus bei Pufferüberlauf (<code>RTE_E_LOST_DATA</code>).</li>\n<li><strong>Signalvalidierung & Filterung:</strong></li>\n<li><code>processingType</code> und <code>limitType</code> dienen Codegeneratoren und Middleware-Layern zur automatischen Injektion von Grenzprüfungen (<code>min</code>/<code>max</code>) oder Filter-Hooks vor Übergabe an die Applikations-Runnable.</li>\n<li><strong>Timing- & Güteüberwachung:</strong></li>\n<li><code>signalAge</code> muss im System-Design mit den Sende- und Task-Perioden der CAN/LIN/FlexRay-Frames abgestimmt sein ($t_{\\text{signalAge}} \\ge t_{\\text{PDU\\_Period}} + t_{\\text{Jitter}} + t_{\\text{Execution}}$). Eine zu straffe Konfiguration führt zu False-Positive-Timeouts.</li>\n<li><strong>Erweiterbarkeit (<code>ExtAnnotation</code>):</strong></li>\n<li>Ermöglicht Tool-Herstellern und Integratoren, OEM-spezifische Attribute durchzureichen, ohne das M2-Schema patchen zu müssen. Entwickler dürfen sich im standardisierten C-Code jedoch nicht auf herstellerspezifische Tags verlassen. In neueren Releases (ab AUTOSAR 3.x/4.x) wurden diese Mechanismen weitgehend durch das strukturierte <code>ComSpec</code>-Modell (<code>ReceiverComSpec</code>, <code>DataFilter</code>, <code>InvalidationPolicy</code>) und Timing Extensions (<code>TIMEX</code>) abgelöst.</li>\n</ul>"}, {"id": "FIG-33abede9afe89ac8", "releases": ["R3.0.7", "R3.1.5", "R3.2.3", "R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (AUTOSAR M2-Metamodell-Ausschnitt, Release R2.1.20).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Definition der Metaklassen für anwendungsspezifische Annotationen (<code>ApplicationAttributes</code>) im Rahmen der Sender-Receiver-Kommunikation. Dient der formalen semantischen Spezifikation von Daten- und Dienstgüteeigenschaften (Quality of Service / Signal-Eigenschaften) an Software-Component-Ports (VFB-Ebene), bevor diese auf konkrete RTE- und Com-Mechanismen abgebildet werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen und Attribute</p>\n<ul class=\"fig-list\">\n<li><strong><code>ApplicationAttributes::PortAnnotation</code>:</strong></li>\n<li>Abstrakte Basisklasse für alle portbezogenen Metadaten-Annotationen.</li>\n<li><strong><code>ApplicationAttributes::SenderReceiverAnnotation</code>:</strong></li>\n<li>Spezialisierung von <code>PortAnnotation</code>.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>computed: Boolean</code> – Flag, ob der Datenwert zur Laufzeit berechnet oder direkt übernommen wird.</li>\n<li><code>limitType: Enumeration{ none, min, max }</code> – Spezifikation von Wertebereichsgrenzen (Grenzprüfung).</li>\n<li><code>processingType: Enumeration{ none, raw, filtered }</code> – Art der Signalverarbeitung vor Weitergabe (Rohwert vs. Vorverarbeitung).</li>\n<li><strong><code>ApplicationAttributes::SenderAnnotation</code>:</strong></li>\n<li>Spezialisierung von <code>SenderReceiverAnnotation</code> zur Spezifikation von Eigenschaften auf Senderseite (P-Port-Kontext).</li>\n<li><strong><code>ApplicationAttributes::ReceiverAnnotation</code>:</strong></li>\n<li>Spezialisierung von <code>SenderReceiverAnnotation</code> für die Empfängerseite (R-Port-Kontext).</li>\n<li><strong>Attribut:</strong></li>\n<li><code>signalAge: Float</code> – Maximal zulässiges Signalalter bzw. Latenz-/Timeout-Toleranz des Signals.</li>\n<li><strong><code>PortInterface::DataElementPrototype</code> (Kategorie <code>DataPrototype</code>):</strong></li>\n<li>Schnittstellenelement eines Sender-Receiver-PortInterface.</li>\n<li><strong>Attribut:</strong></li>\n<li><code>infoType: Enumeration{ data, event }</code> – Semantische Unterscheidung zwischen periodischem/unqued Werttransport (<code>data</code>) und queued/ereignisgetriebenem Nachrichtentransport (<code>event</code>).</li>\n<li><strong><code>ApplicationAttributes::ExtAnnotation</code>:</strong></li>\n<li>Generische Erweiterungsstruktur für proprietäre oder werkzeugspezifische Metadaten.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>name: String</code></li>\n<li><code>value: String</code></li>\n<li><strong>Paket <code>BM Software-Component</code> (Behavior Modeling):</strong></li>\n<li>Übergeordnetes Paket, das die Modellelemente importiert.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong>Vererbung:</strong></li>\n<li><code>SenderReceiverAnnotation</code> erbt von <code>PortAnnotation</code>.</li>\n<li><code>SenderAnnotation</code> und <code>ReceiverAnnotation</code> erben von <code>SenderReceiverAnnotation</code>.</li>\n<li><strong>Assoziation <code>+dataElement</code>:</strong></li>\n<li>Stereotyp: <code>«instanceRefs»</code></li>\n<li>Kardinalität: <code>0..1</code> (<code>SenderReceiverAnnotation</code>) zu <code>1</code> (<code>DataElementPrototype</code>).</li>\n<li>Kontextbezogene Referenzierung des konkreten Datenelements innerhalb des Schnittstellenkontexts.</li>\n<li><strong>Komposition <code>+extAnnotations</code>:</strong></li>\n<li><code>SenderReceiverAnnotation</code> aggregiert via Komposition <code>0..*</code> Instanzen von <code>ExtAnnotation</code>.</li>\n<li><strong>Paket-Abhängigkeiten:</strong></li>\n<li><code>BM Software-Component</code> besitzt <code>«import»</code>-Abhängigkeiten zu <code>PortInterface::DataElementPrototype</code>, <code>ApplicationAttributes::PortAnnotation</code>, <code>ApplicationAttributes::SenderReceiverAnnotation</code> und <code>ApplicationAttributes::ReceiverAnnotation</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Charakter:</strong> Rein statisches M2-Strukturdiagramm; kein direktes Laufzeit-Sequenzdiagramm.</li>\n<li><strong>Statisch determinierte Laufzeitsemantik:</strong></li>\n<li>Die Instanziierung dieser Metaklassen in M1-Beschreibungen (ARXML) steuert die Codegenerierung des RTE-Laufzeitverhaltens:</li>\n<li><code>infoType == event</code> erzwingt Queueing-Mechanismen im RTE-Puffer (<code>Rte_Send</code> / <code>Rte_Receive</code>) mit FIFO-Ablauf.</li>\n<li><code>infoType == data</code> führt zu Last-Is-Best-Semantik (<code>Rte_Write</code> / <code>Rte_Read</code>) ohne Pufferung.</li>\n<li><code>signalAge</code> parametriert Empfangs-Überwachungslogiken (Alive Supervision / Timeout-Monitor im RTE-Task-Kontext). Bei Überschreitung erfolgt die Rückgabe von Fehlercodes (z. B. <code>RTE_E_TIMEOUT</code> / <code>RTE_E_NEVER_RECEIVED</code>) oder Aktivierung von Invalidierungs-/Default-Werten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE-API-Vertrag:</strong></li>\n<li>Die Modellierung von <code>infoType</code> entscheidet direkt über die generierten C-Funktionssignaturen und Pufferallokationen:</li>\n<li><code>data</code>: Nicht-blockierende Lese-/Schreibzugriffe (implicit/explicit Data Access).</li>\n<li><code>event</code>: Queue-basierte Schnittstellen mit Fehlerstatus bei Pufferüberlauf (<code>RTE_E_LOST_DATA</code>).</li>\n<li><strong>Signalvalidierung & Filterung:</strong></li>\n<li><code>processingType</code> und <code>limitType</code> dienen Codegeneratoren und Middleware-Layern zur automatischen Injektion von Grenzprüfungen (<code>min</code>/<code>max</code>) oder Filter-Hooks vor Übergabe an die Applikations-Runnable.</li>\n<li><strong>Timing- & Güteüberwachung:</strong></li>\n<li><code>signalAge</code> muss im System-Design mit den Sende- und Task-Perioden der CAN/LIN/FlexRay-Frames abgestimmt sein ($t_{\\text{signalAge}} \\ge t_{\\text{PDU\\_Period}} + t_{\\text{Jitter}} + t_{\\text{Execution}}$). Eine zu straffe Konfiguration führt zu False-Positive-Timeouts.</li>\n<li><strong>Erweiterbarkeit (<code>ExtAnnotation</code>):</strong></li>\n<li>Ermöglicht Tool-Herstellern und Integratoren, OEM-spezifische Attribute durchzureichen, ohne das M2-Schema patchen zu müssen. Entwickler dürfen sich im standardisierten C-Code jedoch nicht auf herstellerspezifische Tags verlassen. In neueren Releases (ab AUTOSAR 3.x/4.x) wurden diese Mechanismen weitgehend durch das strukturierte <code>ComSpec</code>-Modell (<code>ReceiverComSpec</code>, <code>DataFilter</code>, <code>InvalidationPolicy</code>) und Timing Extensions (<code>TIMEX</code>) abgelöst.</li>\n</ul>"}], "trans": [{"from": "FIG-c5d8de8aa2c6efaf", "to": "FIG-33abede9afe89ac8", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Assoziation <code>+dataElement</code>: Der Stereotyp wurde von <code>«instanceRef»</code> zu <code>«instanceRefs»</code> umbenannt (Schreibweise/Plural).</li>\n<li>Gesamtbild: Neu gerendert mit veränderter Skalierung/Auflösung und leicht abweichendem Schriftdruck, fachlicher Inhalt und Struktur der Metaklassen sind ansonsten identisch geblieben.</li>\n</ul>"}]};
